const j = $input.first().json;
const b = j.body && typeof j.body === 'object' && !Array.isArray(j.body) ? j.body : j;
const prompt = String(b.prompt ?? '');
const klant = String(b.klant ?? 'algemeen');
const difyKey = ($env.DIFY_AGENT_API_KEY || $env.DIFY_RESEARCH_API_KEY || '').trim();
if (!difyKey) {
  return [{
    json: {
      output: 'Factory OS: zet DIFY_AGENT_API_KEY of DIFY_RESEARCH_API_KEY in AI_HQ/.env (Dify app → API Access), daarna docker compose up -d en docker restart n8n.',
      status: 'config_error',
      klant,
      afdeling: 'n/a',
      complexiteit: 'n/a',
    },
  }];
}
return [{ json: { prompt, klant, status: '__ok' } }];

