const inJson = $input.first().json;
const prep = $('Prepare').first().json;
const klant = prep.klant || 'algemeen';
const afdeling = 'factory-os-agent';
const complexiteit = 'normaal';

let answer = inJson.answer;
if (answer == null && inJson.data && typeof inJson.data === 'object' && !Array.isArray(inJson.data) && inJson.data.outputs) {
  const o = inJson.data.outputs;
  answer = o.answer || o.text || o.result;
}
if (answer == null) answer = inJson.text || inJson.message || '';

const sseRaw = (typeof inJson.data === 'string' ? inJson.data : null) || (typeof inJson.body === 'string' ? inJson.body : '') || '';
if (!answer && sseRaw.includes('data:')) {
  let acc = '';
  for (const line of sseRaw.split(/\r?\n/)) {
    const s = line.trim();
    if (!s.startsWith('data:')) continue;
    const payload = s.slice(5).trim();
    if (payload === '[DONE]') continue;
    try {
      const j = JSON.parse(payload);
      if (j.event === 'agent_message' && typeof j.answer === 'string') acc += j.answer;
      else if (j.event === 'message' && typeof j.answer === 'string') acc += j.answer;
      else if (j.answer && typeof j.answer === 'string') acc += j.answer;
    } catch (e) {}
  }
  answer = acc;
}

if (typeof answer !== 'string') answer = JSON.stringify(answer || '');
if (!answer && inJson.error) answer = 'Dify/HTTP-fout: ' + String(inJson.error.message || JSON.stringify(inJson.error)).slice(0, 800);
if (!answer) answer = 'Geen antwoord van Dify (check DIFY_AGENT_API_KEY of DIFY_RESEARCH_API_KEY, FACTORY_OS_DIFY_API_BASE).';

const datum = new Date().toLocaleDateString('nl-NL');
const lines = answer.split('\n');
const summary = lines.slice(0, 3).join('\n');
const isErr = !String(answer || '').trim() || String(answer).startsWith('Dify/HTTP-fout') || String(answer).includes('Geen antwoord van Dify');

const trimmed = String(answer).trim();
const looksStructured = /^#\s/m.test(trimmed) || /\n##\s/.test(trimmed) || trimmed.includes('## Samenvatting') || trimmed.includes('# Factory OS Response');
const lineCount = trimmed.split(/\n/).length;
const isSimple = !isErr && !looksStructured && trimmed.length <= 1200 && lineCount <= 4;

let output;
if (isSimple) {
  output = trimmed;
} else {
  output = `# Factory OS Response\n**Klant:** ${klant} · **Agent:** ${afdeling} · **Datum:** ${datum}\n\n## Samenvatting\n${summary}\n\n## Volledige response\n${answer}\n\n---\n*Factory OS · Dify all-in-one · ${complexiteit}*`;
}

return [{
  json: {
    output,
    answer_raw: answer,
    afdeling,
    complexiteit,
    klant,
    status: isErr ? 'error' : 'ok',
    model: 'dify-factory-os-agent',
  },
}];
